def find_Max(arr):
    """
    Find the maximum element in a sorted and rotated array.
    Assumes no duplicates in the array.
    """
    if not arr:
        return None  # or raise an error if empty array is not allowed

    low, high = 0, len(arr) - 1

    # If array is not rotated at all
    if arr[low] < arr[high]:
        return arr[high]

    while low <= high:
        mid = (low + high) // 2
        # Check if mid is the max
        if mid < len(arr) - 1 and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # Check if mid-1 is the max
        if mid > 0 and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which side to go
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1

    return arr[0]  # fallback, though should never reach here

