    while True:
        rhs = n - a * x
        # Check if rhs is divisible by b and y is integer
        if b != 0 and rhs % b == 0:
            y = rhs // b
            if y >= 0:
                return (x, y)
        elif b == 0:
            # If b=0, then equation is a*x = n, y can be anything
            if a != 0 and n % a == 0:
                x_sol = n // a
                if x_sol >= 0:
