def get_total_number_of_sequences(N, K):
    # dp[i][k]: number of sequences of length k starting with i
    # We'll compute dp bottom-up from k=1 to K
    # For k=1, dp[i][1] = 1 for all i <= N
    # For k>1, dp[i][k] = sum of dp[j][k-1] for all j >= 2*i and j <= N

    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: sequences of length 1
    for i in range(1, N + 1):
        dp[i][1] = 1

    for length in range(2, K + 1):
        # To efficiently compute sum of dp[j][length-1] for j >= 2*i,
        # we precompute suffix sums for dp[*][length-1]
        suffix_sum = [0] * (N + 2)
        for x in range(N, 0, -1):
            suffix_sum[x] = suffix_sum[x + 1] + dp[x][length - 1]

        for i in range(1, N + 1):
            start = 2 * i
            if start <= N:
                dp[i][length] = suffix_sum[start]
            else:
                dp[i][length] = 0

    # Total sequences of length K is sum of dp[i][K] for all i in [1..N]
    return sum(dp[i][K] for i in range(1, N + 1))

