def reverse_Array_Upto_K(seq, k):
    """
    Reverse the first k+1 elements of the input sequence and return a new sequence of the same type.

    Parameters:
    seq (sequence): Input sequence (list, tuple, etc.)
    k (int): zero-based index up to which the sequence prefix is reversed

    Returns:
    sequence: New sequence of the same type as seq with first k+1 elements reversed
    """
    if not seq:
        return seq  # empty sequence, return as is

    # Ensure k is within bounds
    k = min(k, len(seq) - 1)

    prefix_reversed = seq[:k+1][::-1]
    suffix = seq[k+1:]

    # Reconstruct sequence of same type
    if isinstance(seq, list):
        return prefix_reversed + suffix
    elif isinstance(seq, tuple):
        return tuple(prefix_reversed) + suffix
    elif isinstance(seq, str):
        return ''.join(prefix_reversed) + suffix
    else:
        # For other sequence types, try to reconstruct using the type constructor
        try:
            return type(seq)(prefix_reversed) + suffix
        except TypeError:
            # If can't add, try concatenation with type(seq)(suffix)
            try:
                return type(seq)(prefix_reversed) + type(seq)(suffix)
            except Exception:
                # fallback: just return list version
                return list(prefix_reversed) + list(suffix)

